struct Customer { int customerId; string customerName; };

class Solution {
public:
    vector<int> findMissingIds(vector<Customer>& customers) {
        int mx = 0;
        for (auto& c : customers) mx = max(mx, c.customerId);
        vector<int> res;
        for (int i = 1; i <= mx; ++i) {
            bool found = false;
            for (auto& c : customers)
                if (c.customerId == i) { found = true; break; }
            if (!found) res.push_back(i);
        }
        return res;
    }
};

