        List<Integer> res = new ArrayList<>();
        for (int i = 1; i <= mx; i++) {
            boolean found = false;
            for (Customer c : customers)
                if (c.customerId == i) { found = true; break; }
            if (!found) res.add(i);
        }
        return res;
    }
}

