import pandas as pd

class Solution:
    def find_missing_ids(self, customers: pd.DataFrame) -> pd.DataFrame:
        present = set(customers.customer_id.tolist())
        mx = int(customers.customer_id.max())
        missing = [i for i in range(1, mx + 1) if i not in present]
        return pd.DataFrame(missing, columns=['ids'])

